[RequireComponent(typeof(CharacterController))]
public class TopDownShooterInput : MonoBehaviour
{
    [Header("Settings")]
    [SerializeField] private float moveSpeed = 5f;
    [SerializeField] private float gravity = -9.81f;

    [Header("Actions")]
    [SerializeField] private InputActionReference moveAction;
    [SerializeField] private InputActionReference aimAction;
    [SerializeField] private InputActionReference fireAction;

    private CharacterController controller;
    private Vector3 velocity;

    private void Awake()
    {
        controller = GetComponent<CharacterController>();
    }

    private void OnEnable()
    {
        moveAction.action.Enable();
        aimAction.action.Enable();
        fireAction.action.Enable();

        fireAction.action.performed += OnFirePerformed;
    }

    private void OnDisable()
    {
        moveAction.action.Disable();
        aimAction.action.Disable();
        fireAction.action.Disable();

        fireAction.action.performed -= OnFirePerformed;
    }

    private void Update()
    {
        // Movement
        Vector2 moveInput = moveAction.action.ReadValue<Vector2>();
        Vector3 move = new Vector3(moveInput.x, 0, moveInput.y);
        controller.Move(move * moveSpeed * Time.deltaTime);

        // Rotation (Aiming)
        Vector2 mousePos = aimAction.action.ReadValue<Vector2>();
        Ray ray = Camera.main.ScreenPointToRay(mousePos);
        if (Physics.Raycast(ray, out RaycastHit hit))
        {
            Vector3 targetPos = hit.point;
            targetPos.y = transform.position.y; // Keep rotation on XZ plane
            Vector3 direction = targetPos - transform.position;
            if (direction != Vector3.zero)
            {
                transform.rotation = Quaternion.LookRotation(direction);
            }
        }

        // Simple Gravity
        if (controller.isGrounded && velocity.y < 0) velocity.y = -2f;
        velocity.y += gravity * Time.deltaTime;
        controller.Move(velocity * Time.deltaTime);
    }

    private void OnFirePerformed(InputAction.CallbackContext context)
    {
        Fire();
    }

    private void Fire()
    {
        Debug.Log("Fire action triggered!");
    }
}
