```csharp
using UnityEngine;
using System.Collections.Generic;

public interface IDamageable
{
    void TakeDamage(float amount);
}

public class Explosion : MonoBehaviour
{
    [Header("Settings")]
    [SerializeField] private float radius = 5f;
    [SerializeField] private float maxDamage = 100f;
    [SerializeField] private float explosionForce = 500f;
    [SerializeField] private float upwardsModifier = 2f;

    [Header("Layers")]
    [SerializeField] private LayerMask damageMask;
    [SerializeField] private LayerMask obstacleMask;

    private readonly Collider[] _colliderBuffer = new Collider[64];
    private readonly HashSet<Rigidbody> _processedBodies = new HashSet<Rigidbody>();
    private readonly HashSet<IDamageable> _processedDamageables = new HashSet<IDamageable>();

    public void Explode()
    {
        Vector3 center = transform.position;
        int count = Physics.OverlapSphereNonAlloc(center, radius, _colliderBuffer, damageMask, QueryTriggerInteraction.Ignore);

        _processedBodies.Clear();
        _processedDamageables.Clear();

        for (int i = 0; i < count; i++)
        {
            Collider col = _colliderBuffer[i];

            // Line of sight check
            Vector3 dir = (col.bounds.center - center).normalized;
            if (Physics.Raycast(center, dir, out RaycastHit hit, radius, obstacleMask, QueryTriggerInteraction.Ignore))
            {
                if (hit.collider != col) continue; // Blocked by something else
            }

            float distance = Vector3.Distance(center, col.ClosestPoint(center));
            float damageMultiplier = Mathf.Clamp01(1f - (distance / radius));
            float finalDamage = maxDamage * damageMultiplier;

            // Handle Damage
            IDamageable damageable = col.GetComponent<IDamageable>();
            if (damageable == null)
            {
                // Check parents for IDamageable
                Transform parent = col.transform.parent;
                while (parent != null)
                {
                    damageable = parent.GetComponent<IDamageable>();
                    if (damageable != null) break;
                    parent = parent.parent;
                }
            }

            if (damageable != null && _processedDamageables.Add(damageable))
            {
                damageable.TakeDamage(finalDamage);
            }

            // Handle Physics
            Rigidbody rb = col.GetComponent<Rigidbody>();
            if (rb != null && _processedBodies.Add(rb))
            {
                rb.AddExplosionForce(explosionForce, center, radius, upwardsModifier, ForceMode.Impulse);
            }
        }
    }
}
```

One common mistake to avoid is forgetting to set the `damageMask` and `obstacleMask` in the Inspector; if they are left at "Nothing," the explosion won't detect any objects!

