	StopFire();
	Super::EndPlay(EndPlayReason);
}

void UHitscanWeaponComponent::StartFire()
{
	float FireInterval = 60.0f / RoundsPerMinute;
	float CurrentTime = GetWorld()->GetTimeSeconds();

	if (CurrentTime < NextFireTime)
	{
		NextFireTime = CurrentTime + (NextFireTime - CurrentTime); // Simple logic to maintain rhythm
	}

	GetWorld()->GetTimerManager().SetTimer(FireTimerHandle, this, &UHitscanWeaponComponent::FireShot, FireInterval, true);
}

void UHitscanWeaponComponent::StopFire()
{
	GetWorld()->GetTimerManager().ClearTimer(FireTimerHandle);
}

void UHitscanWeaponComponent::FireShot()
{
	APawn* OwnerPawn = Cast<APawn>(GetOwner());
	if (!OwnerPawn) return;

	FVector EyeLocation;
	FRotator EyeRotation;
	OwnerPawn->GetActorEyesViewPoint(EyeLocation, EyeRotation);

	FVector ForwardVector = EyeRotation.Vector();
	FVector SpreadVector = FVector(
		FMath::FRandRange(-SpreadDegrees, SpreadDegrees),
		FMath::FRandRange(-SpreadDegrees, SpreadDegrees),
		0.0f
	);

	FVector FinalDirection = (ForwardVector + SpreadVector).GetSafeNormal();
	FVector TraceEnd = EyeLocation + (FinalDirection * Range);

	FHitResult Hit;
	FCollisionQueryParams Params;
	Params.AddIgnoredActor(GetOwner());

	if (GetWorld()->LineTraceSingleByChannel(Hit, EyeLocation, TraceEnd, ECC_Visibility, Params))
	{
		AController* PC = OwnerPawn->GetController();
		UGameplayStatics::ApplyPointDamage(Hit.GetActor(), Damage, FinalDirection, Hit, PC, GetOwner(), DamageTypeClass);
	}

	// Debug line to see your shots in the editor!
	DrawDebugLine(GetWorld(), EyeLocation, TraceEnd, FColor::Red, false, 1.0f);
}
```

