int32 UInventoryComponent::AddItem(FName ItemId, int32 Amount)
{
    if (!HasAuthority()) return -1;

    int32 CurrentCount = GetCount(ItemId);
    UpdateInventory(ItemId, Amount, true);
    return GetCount(ItemId);
}

bool UInventoryComponent::RemoveItem(FName ItemId, int32 Amount)
{
    if (!HasAuthority()) return false;

    int32 CurrentCount = GetCount(ItemId);
    if (CurrentCount >= Amount)
    {
        UpdateInventory(ItemId, Amount, false);
        return true;
    }
    return false;
}

int32 UInventoryComponent::GetCount(FName ItemId) const
{
    for (const FInventoryEntry& Entry : Inventory)
    {
        if (Entry.ItemId == ItemId) return Entry.Count;
    }
    return 0;
}

void UInventoryComponent::ServerUseItem_Implementation()
{
    if (RemoveItem(ItemId, 1))
    {
        OnInventoryUpdated.Broadcast();
    }
}

void UInventoryComponent::UpdateInventory(FName ItemId, int32 Amount, bool bIsAddition)
{
    int32 Index = -1;
    for (int32 i = 0; i < Inventory.Num(); ++i)
    {
        if (Inventory[i].ItemId == ItemId) { Index = i; break; }
    }

    if (bIsAddition)
    {
        if (Index != -1) Inventory[Index].Count += Amount;
        else Inventory.Add(FInventoryEntry(ItemId, Amount));
    }
    else
    {
        if (Index != -1)
        {
            Inventory[Index].Count -= Amount;
            if (Inventory[Index].Count <= 0) Inventory.RemoveAt(Index);
        }
    }

    OnItemCountChanged.Broadcast(ItemId);
    OnInventoryUpdated.Broadcast();
}

void UInventoryComponent::OnRep_Inventory()
{
    OnInventoryUpdated.Broadcast();
}
```

