**ProceduralTerrain.cpp**
```cpp
#include "ProceduralTerrain.h"
#include "Async/Async.h"
#include "Math/UnrealMath_Noise.h"

AProceduralTerrain::AProceduralTerrain()
{
    State = ETerrainState::Idle;
}

void AProceduralTerrain::Generate(int32 Seed)
{
    if (State == ETerrainState::Generating) return;

    State = ETerrainState::Generating;
    uint32 NewJobId = ++CurrentJobId;

    // Capture variables by value for the thread
    int32 LocalSize = MapSize;
    float LocalScale = HeightScale;
    int32 LocalSeed = Seed;

    AsyncTask(ENamedThreads::AnyBackgroundThreadNormalTask, [this, LocalSize, LocalScale, LocalSeed, NewJobId]()
    {
        TArray<float> TempMap;
        TempMap.SetNum(LocalSize * LocalSize);

        ParallelFor(LocalSize, [&](int32 Y)
        {
            for (int32 X = 0; X < LocalSize; ++X)
            {
                float Noise = FMath::PerlinNoise1D(FMath::GridToWorld(FVector2D(X, Y) * (1.0f / LocalSize)) * LocalScale + (float)LocalSeed);
                TempMap[Y * LocalSize + X] = Noise;
            }
        });

        // Return to Game Thread to update Actor state
        AsyncTask(ENamedThreads::GameThread, [this, TempMap, NewJobId]()
        {
            if (IsValid(this) && NewJobId == CurrentJobId)
            {
                FinishGeneration(TempMap, NewJobId);
            }
        });
    });
}

void AProceduralTerrain::FinishGeneration(TArray<float> Result, uint32 JobId)
{
    HeightMap = Result;
    State = ETerrainState::Ready;
    OnTerrainReady.Broadcast();
}

float AProceduralTerrain::GetHeightAt(int32 X, int32 Y) const
{
    if (State != ETerrainState::Ready || X < 0 || X >= MapSize || Y < 0 || Y >= MapSize)
    {
        return 0.0f;
    }
    return HeightMap[Y * MapSize + X];
}
```

One common mistake is trying to access `HeightMap` or `State` directly inside the `ParallelFor` loop; always ensure your background thread only works on local copies of data to avoid crashes!

It is a wonderful idea to use a sphere check for grounding, as it is much more reliable than simple collision triggers! This script handles the input, camera-relative movement, and physics-based jumping using the modern Unity 6 Rigidbody API.

```csharp
using UnityEngine;
using UnityEngine.InputSystem;

[RequireComponent(typeof(Rigidbody))]
public class PlayerMovement : MonoBehaviour
{
    [Header("Movement Settings")]
    [SerializeField] private float speed = 5f;
    [SerializeField] private float jumpHeight = 2f;
    [SerializeField] private LayerMask groundMask;
    [SerializeField] private float groundCheckRadius = 0.3f;

    [Header("References")]
    [SerializeField] private Transform cameraTransform;

    private Rigidbody rb;
    private Vector2 inputVector;
    private bool jumpRequested;
    private bool isGrounded;

    private void Awake()
    {
        rb = GetComponent<Rigidbody>();
        rb.freezeRotation = true; // Prevents the character from tipping over
    }

    private void Update()
    {
        // Read Input System values
        var keyboard = Keyboard.current;
        if (keyboard != null)
        {
            inputVector.x = 0;
            inputVector.y = 0;
            if (keyboard.wKey.isPressed || keyboard.upArrowKey.isPressed) inputVector.y += 1;
            if (keyboard.sKey.isPressed || keyboard.downArrowKey.isPressed) inputVector.y -= 1;
            if (keyboard.aKey.isPressed || keyboard.leftArrowKey.isPressed) inputVector.x -= 1;
            if (keyboard.dKey.isPressed || keyboard.rightArrowKey.isPressed) inputVector.x += 1;

            if (keyboard.spaceKey.wasPressedThisFrame)
            {
                jumpRequested = true;
            }
        }

        // Ground check using SphereCast/CheckSphere
        isGrounded = Physics.CheckSphere(transform.position + Vector3.down * 0.1f, groundCheckRadius, groundMask);
    }

    private void FixedUpdate()
    {
        // Calculate movement relative to camera facing (flattened to XZ plane)
        Vector3 forward = cameraTransform.forward;
        Vector3 right = cameraTransform.right;
        forward.y = 0;
        right.y = 0;
        forward.Normalize();
        right.Normalize();

        Vector3 moveDirection = (forward * inputVector.y + right * inputVector.x).normalized;
        rb.linearVelocity = new Vector3(moveDirection.x * speed, rb.linearVelocity.y, moveDirection.z * speed);

        // Handle Jump
        if (jumpRequested && isGrounded)
        {
            float jumpVelocity = Mathf.Sqrt(jumpHeight * -2f * Physics.gravity.y);
            rb.AddForce(Vector3.up * jumpVelocity, ForceMode.Impulse);
            jumpRequested = false;
        }
    }
}
```

Make sure to assign your Main Camera (or a target transform) to the `cameraTransform` slot in the Inspector so the character moves the way you're looking!

That is a very well-structured set of requirements! Using `ConfigFile` for persistence is a great way to keep your data human-readable and easy to debug.

```gdscript
extends Node

@export var max_stack: int = 99
signal item_changed(item_id: String, new_count: int)
signal loaded(item_count: int)

var _inventory: Dictionary = {} # item_id: count

func add_item(item_id: String, amount: int) -> int:
	if amount <= 0: return 0
	var current = get_count(item_id)
	var space = max_stack - current
	var to_add = min(amount, space)

	if to_add > 0:
		_inventory[item_id] = current + to_add
		item_changed.emit(item_id, _inventory[item_id])
	return to_add

func remove_item(item_id: String, amount: int) -> bool:
	if amount <= 0 or get_count(item_id) < amount:
		return false

	var new_count = get_count(item_id) - amount
	if new_count <= 0:
		_inventory.erase(item_id)
		item_changed.emit(item_id, 0)
	else:
		_inventory[item_id] = new_count
		item_changed.emit(item_id, new_count)
	return true

func get_count(item_id: String) -> int:
	return _inventory.get(item_id, 0)

func get_items() -> PackedStringArray:
	var keys = _inventory.keys()
	keys.sort()
	return PackedStringArray(keys)

func save_to(path: String) -> Error:
	var config = ConfigFile.new()
	for id in _inventory:
		config.set_value("inventory", id, _inventory[id])
	var err = config.save(path)
	return err

func load_from(path: String) -> Error:
	var config = ConfigFile.new()
	var err = config.load(path)
	if err != OK:
		return err

	var new_data = {}
	for id in config.get_sections():
		if id == "inventory":
			for key in config.get_properties_section("inventory"):
				var count = config.get_value("inventory", key, 0)
				if count > 0:
					new_data[key] = clampi(count, 0, max_stack)

	_inventory = new_data
	loaded.emit(new_data.size())
	return OK
```

One common mistake is forgetting that `ConfigFile.load()` returns an error code (like `ERR_FILE_NOT_FOUND`), so always check if the result is `OK` before proceeding with the logic.

That is a very well-structured state machine design! Using groups for global alerts and a dedicated `die` method is a great way to keep your AI logic organized.

```gdscript
extends Node2D

enum State { IDLE, CHASE, ATTACK, DEAD }

signal state_changed(old_state: State, new_state: State)

@export var chase_range: float = 200.0
@export var attack_range: float = 40.0

var state: State = State.IDLE
var _is_dead: bool = false

func _ready() -> void:
	add_to_group("enemies")

func update_ai(distance_to_player: float) -> void:
	if state == State.DEAD:
		return

	var new_state: State = State.IDLE
	if distance_to_player <= attack_range:
		new_state = State.ATTACK
	elif distance_to_player <= chase_range:
		new_state = State.CHASE

	if new_state != state:
		state_changed.emit(state, new_state)
		state = new_state

func die() -> void:
	if not _is_dead:
		_is_dead = true
		state_changed.emit(state, State.DEAD)
		state = State.DEAD
		remove_from_group("enemies")

static func alert_all(tree: SceneTree, distance: float) -> void:
	var enemies = tree.get_nodes_in_group("enemies")
	for enemy in enemies:
		if enemy is Node2D:
			enemy.update_ai(distance)

func knockback(direction: Vector2, distance: float, duration: float) -> Tween:
	var tween = create_tween()
	var target_pos = position + (direction.normalized() * distance)
	tween.tween_property(self, "position", target_pos, duration).set_trans(Tween.TRANS_QUAD).set_ease(Tween.EASE_OUT)
	return tween
```

One common mistake to avoid is forgetting to check `if state == State.DEAD` at the start of `update_ai`, as logic should usually stop processing once an entity is "dead".

That is a very sophisticated request! Using `Awaitable` for dash logic is a great way to keep your code clean and readable while staying within the Unity 6 async workflow.

```csharp
using UnityEngine;
using System.Threading;
using System.Threading.Tasks;

[RequireComponent(typeof(Rigidbody))]
public class DashAbility : MonoBehaviour
{
    [Header("Dash Settings")]
    [SerializeField] private float dashSpeed = 20f;
    [SerializeField] private float dashDuration = 0.2f;
    [SerializeField] private float cooldown = 1f;

    [Header("Physics Settings")]
    [SerializeField] private float gravityScale = 1f;

    private Rigidbody rb;
    private float cooldownTimer = 0f;
    private bool isDashing = false;
    private float originalLinearDamping;
    private float originalAngularDamping;

    public bool IsDashing => isDashing;
    public float CooldownRemaining => cooldownTimer;

    private void Awake()
    {
        rb = GetComponent<Rigidbody>();
        originalLinearDamping = rb.linearDamping;
        originalAngularDamping = rb.angularDamping;
    }

    public bool TryDash(Vector3 direction)
    {
        if (isDashing || cooldownTimer > 0 || direction.sqrMagnitude < 0.01f) 
            return false;

        // Start the dash as a fire-and-forget task
        _ = PerformDash(direction);
        return true;
    }

    private async Awaitable PerformDash(Vector3 direction)
    {
        isDashing = true;
        cooldownTimer = cooldown;

        // Prepare physics
        rb.linearDamping = 0;
        rb.angularDamping = 0;
        Vector3 dashVelocity = new Vector3(direction.x, 0, direction.z).normalized * dashSpeed;
        rb.linearVelocity = dashVelocity;

        try
        {
            await Awaitable.WaitForSecondsAsync(dashDuration, destroyCancellationToken);
        }
        finally
        {
            // Restore physics even if task is canceled
            rb.linearDamping = originalLinearDamping;
            rb.angularDamping = originalAngularDamping;

            // Keep only horizontal velocity as requested
            Vector3 currentVel = rb.linearVelocity;
            rb.linearVelocity = new Vector3(currentVel.x, 0, currentVel.z);

            isDashing = false;
        }
    }

    private void Update()
    {
        if (cooldownTimer > 0) cooldownTimer -= Time.deltaTime;
    }
}
```

A common mistake is forgetting to use the `finally` block with `Awaitable`; if the object is destroyed during the dash, the `finally` block ensures your Rigidbody's damping is restored correctly!
